from kodi_six import xbmc


class InfoTagHelper(object):
    """Kodi 20+ InfoTagVideo helpers.

    Value conversion follows ListItem.setInfo("video"): the same checks that
    used to live next to the Kodi 20 call sites in navigation.py.
    """

    # ListItem fields that setInfo() still sets without the deprecation warning
    LISTITEM_INFO_KEYS = ("count", "size", "overlay", "date")

    @staticmethod
    def _int(value):
        try:
            return int(value)
        except (TypeError, ValueError):
            try:
                return int(float(value))
            except (TypeError, ValueError):
                return 0

    @staticmethod
    def _float(value):
        try:
            return float(value)
        except (TypeError, ValueError):
            return 0.0

    @staticmethod
    def _votes(value):
        # setInfo() kept only the digits, e.g. "12,345"
        return int("".join(c for c in str(value) if c.isdigit()) or 0)

    @staticmethod
    def _str(value):
        return value if isinstance(value, str) else str(value)

    @staticmethod
    def _list(value):
        if isinstance(value, (list, tuple)):
            return [InfoTagHelper._str(v) for v in value]
        # shortcut: Kodi splits strings by advancedsettings' videolibrary/itemseparator, assume the default;
        # the daemon sends these fields as lists, so read the setting only if strings start coming through
        return InfoTagHelper._str(value).split(" / ") if value else []

    @classmethod
    def apply_video(cls, list_item, info_tag, labels):
        """Kodi 20+ replacement for setInfo("video"), which logs a deprecation warning on every call."""
        rest = {}
        lowered = {key.lower(): value for key, value in labels.items()}
        for key, value in lowered.items():
            if key in cls.LISTITEM_INFO_KEYS:
                rest[key] = value
            elif key == "rating":
                # setRating() resets votes, so pass them together
                info_tag.setRating(cls._float(value), cls._votes(lowered.get("votes", 0)))
            elif key == "votes" and "rating" in lowered:
                continue
            elif key in cls.VIDEO_INFO_SETTERS:
                setter, convert = cls.VIDEO_INFO_SETTERS[key]
                getattr(info_tag, setter)(convert(value))
        if rest:
            list_item.setInfo("video", rest)

    @staticmethod
    def apply_cast(info_tag, castmembers):
        actors = []
        for castmember in castmembers:
            # Actor() throws if name is empty; ListItem.setCast() did not
            name = castmember.get("name") or ""
            if not isinstance(name, str):
                name = str(name)
            if not name.strip():
                continue
            # infolabels JSON parses numbers as strings; Actor.order must be an int
            order = castmember.get("order", -1)
            try:
                order = int(order)
            except (TypeError, ValueError):
                order = -1
            actors.append(xbmc.Actor(name=name,
                                     role=InfoTagHelper._str(castmember.get("role") or ""),
                                     thumbnail=InfoTagHelper._str(castmember.get("thumbnail") or ""),
                                     order=order))
        if actors:
            info_tag.setCast(actors)

    @staticmethod
    def apply_stream_info(info_tag, stream_info):
        for type_, values in stream_info.items():
            if type_ == "video":
                video_stream_detail = xbmc.VideoStreamDetail(
                    width=values.get('width', 0),
                    height=values.get('height', 0),
                    aspect=values.get('aspect', 0),
                    duration=values.get('duration', 0),
                    codec=values.get('codec', ''),
                    language=values.get('language', ''),
                )
                info_tag.addVideoStream(video_stream_detail)
            elif type_ == "audio":
                audio_stream_detail = xbmc.AudioStreamDetail(
                    language=values.get('language', ''),
                    codec=values.get('codec', ''),
                    channels=values.get('channels', -1),
                )
                info_tag.addAudioStream(audio_stream_detail)
            elif type_ == "subtitle":
                subtitle_stream_detail = xbmc.SubtitleStreamDetail(
                    language=values.get('language', ''),
                )
                info_tag.addSubtitleStream(subtitle_stream_detail)

    @staticmethod
    def apply_resume_point(info_tag, properties):
        if "resumetime" in properties and "totaltime" in properties:
            info_tag.setResumePoint(
                float(properties["resumetime"]),
                float(properties["totaltime"]),
            )
            del properties["resumetime"]
            del properties["totaltime"]


# setInfo("video") keys and their InfoTagVideo setters, converting values the way setInfo() did.
# Stored as plain functions: a staticmethod object is not callable until looked up on the class.
InfoTagHelper.VIDEO_INFO_SETTERS = {
    "dbid": ("setDbId", InfoTagHelper._int),
    "year": ("setYear", InfoTagHelper._int),
    "episode": ("setEpisode", InfoTagHelper._int),
    "season": ("setSeason", InfoTagHelper._int),
    "sortepisode": ("setSortEpisode", InfoTagHelper._int),
    "sortseason": ("setSortSeason", InfoTagHelper._int),
    "episodeguide": ("setEpisodeGuide", InfoTagHelper._str),
    "showlink": ("setShowLinks", InfoTagHelper._list),
    "top250": ("setTop250", InfoTagHelper._int),
    "setid": ("setSetId", InfoTagHelper._int),
    "tracknumber": ("setTrackNumber", InfoTagHelper._int),
    "userrating": ("setUserRating", InfoTagHelper._int),
    "watched": ("setPlaycount", InfoTagHelper._int),
    "playcount": ("setPlaycount", InfoTagHelper._int),
    "artist": ("setArtists", InfoTagHelper._list),
    "genre": ("setGenres", InfoTagHelper._list),
    "country": ("setCountries", InfoTagHelper._list),
    "director": ("setDirectors", InfoTagHelper._list),
    "mpaa": ("setMpaa", InfoTagHelper._str),
    "plot": ("setPlot", InfoTagHelper._str),
    "plotoutline": ("setPlotOutline", InfoTagHelper._str),
    "title": ("setTitle", InfoTagHelper._str),
    "originaltitle": ("setOriginalTitle", InfoTagHelper._str),
    "sorttitle": ("setSortTitle", InfoTagHelper._str),
    "duration": ("setDuration", InfoTagHelper._int),
    "studio": ("setStudios", InfoTagHelper._list),
    "tagline": ("setTagLine", InfoTagHelper._str),
    "writer": ("setWriters", InfoTagHelper._list),
    "credits": ("setWriters", InfoTagHelper._list),
    "tvshowtitle": ("setTvShowTitle", InfoTagHelper._str),
    "premiered": ("setPremiered", InfoTagHelper._str),
    "status": ("setTvShowStatus", InfoTagHelper._str),
    "set": ("setSet", InfoTagHelper._str),
    "setoverview": ("setSetOverview", InfoTagHelper._str),
    "tag": ("setTags", InfoTagHelper._list),
    "imdbnumber": ("setIMDBNumber", InfoTagHelper._str),
    "code": ("setProductionCode", InfoTagHelper._str),
    "aired": ("setFirstAired", InfoTagHelper._str),
    "lastplayed": ("setLastPlayed", InfoTagHelper._str),
    "album": ("setAlbum", InfoTagHelper._str),
    "votes": ("setVotes", InfoTagHelper._votes),
    "trailer": ("setTrailer", InfoTagHelper._str),
    "path": ("setPath", InfoTagHelper._str),
    "filenameandpath": ("setFilenameAndPath", InfoTagHelper._str),
    "dateadded": ("setDateAdded", InfoTagHelper._str),
    "mediatype": ("setMediaType", InfoTagHelper._str),
}
